      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Overall housing is approximately left-right symmetric about a vertical mid-plane, but symmetry is broken by the right-side steam wand and local control/feature cutouts."
  },
